 .popup-overlay {
 display: none;
 position: fixed;
 top: 0; left: 0;
 width: 100%; height: 100%;
 background: rgba(0, 0, 0, 0.7);
 z-index: 999999;
 justify-content: center;
 align-items: center;
 padding: 0 20px;
 }
 .home .popup-overlay.show { display: flex; }
 .popup-content {
 max-width: 500px;
 text-align: center;
 margin: 70px auto;
 max-height: 610px;
 background: #fff;
 position: relative;
 display: flex;
 flex-direction: column;
 overflow: hidden;
 }
 .popup-body {
 flex: 1 1 auto;
 overflow-y: auto;
 -webkit-overflow-scrolling: touch;
 }
 .popup-body img {
 width: 100%;
 height: auto;
 display: block;
 }
 .popup-footer {
 flex: 0 0 auto;
 display: flex;
 justify-content: center;
 align-items: stretch;
 background: #fff;
 color: #000;
 font-size: 14px;
 text-align: center;
 border-top: 1px solid #d9d9d9; /* 상단 라인 */
 font-weight:500;
 }
 .popup-footer div {
 flex: 1;
 cursor: pointer;
 display: flex;
 align-items: center;
 justify-content: center;
 padding: 13px 0;
 }
 .popup-footer div + div {
 border-left: 1px solid rgba(255, 255, 255, 0.3);
 }
 .popup-footer div:hover {
 background: rgba(255, 255, 255, 0.1);
 text-decoration: underline;
 }
 .popup-footer div + div {
 border-left: 1px solid #d9d9d9;
 }
 .popup-footer div:first-child {
 color: rgba(0, 0, 0, 0.4);
 }
 @media (max-width: 500px) {
 .popup-footer {
 font-size: 13px;
 }
 .popup-footer div {
 padding: 13px 0;
 }
 }
